INSERT INTO DimTime (SK_TimeID, TimeValue, HourID, HourDesc, MinuteID, MinuteDesc, SecondID, SecondDesc, MarketHoursFlag, OfficeHoursFlag) SELECT CAST(Time.SK_TimeID AS INT) AS SK_TimeID, CAST(TimeValue AS TIME) AS TimeValue, CAST(HourID AS DECIMAL(2, 0)) AS HourID, CAST(HourDesc AS TEXT) AS HourDesc, CAST(Time.MinuteID AS DECIMAL(2, 0)) AS MinuteID, CAST(Time.MinuteDesc AS TEXT) AS MinuteDesc, CAST(SecondID AS DECIMAL(2)) AS SecondID, CAST(SecondDesc AS TEXT) AS SecondDesc, CAST(MarketHoursFlag AS BOOLEAN) AS MarketHoursFlag, CAST(OfficeHoursFlag AS BOOLEAN) AS OfficeHoursFlag FROM Source.Time;
